def transform(grid):
    h,w=len(grid),len(grid[0])
    groups={}
    for r in range(h):
        for c in range(w):
            if grid[r][c]: groups.setdefault(grid[r][c],[]).append((r,c))
    if not groups: return [row[:] for row in grid]
    color=max(groups,key=lambda k:len(groups[k]))
    pts=groups[color]
    a,b=min(r for r,c in pts),max(r for r,c in pts)
    l,t=min(c for r,c in pts),max(c for r,c in pts)
    inside=[(r,c) for r in range(a+1,b) for c in range(l+1,t) if grid[r][c]!=0]
    out=[[0]*w for _ in range(h)]
    keep=inside if inside else pts
    for r,c in keep: out[r][c]=grid[r][c]
    return out

